-- FLL-TP-RHIZOM-2023 · coverage wave block 4b (2026-09-29): GATE PROPOSALS + required-flag/visibility changes that read the block-4a fields. SIGN-OFF REQUIRED (Alvaro):
-- REQ-06 abutment exemption + watertight control vessels; REQ-10 / REQ-14 scaled to the vessel (B-3); REQ-22 guarded by the extension request (B-4);
-- new REQ-23…REQ-26; the abutment and extension fields become conditional (visible_when) and optional so a Gussasphalt test / a first-issue report can complete.
-- Quotes = rendered PDF pages read in-session 2026-09-29 (VA). Each item carries its print basis and its open RULING.
-- Apply ONLY after block 4a and after the rulings: node scripts/apply-migration.mjs scripts/migrations/20260929230100_fll_tp_rhizom_gates_coverage_block4b.sql
-- Rollback: scripts/migrations/rollback-20260929230100_fll_tp_rhizom_gates_coverage_block4b.sql
BEGIN;
UPDATE fields f SET is_required = false, visible_when = 'widerlager_eingebaut == true' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND w.code = 'FLLTP-RHZ-05' AND s.code = 'FLL-TP-RHIZOM-2023' AND f.symbol = 'widerlager_dicke_mm' AND f.is_required = true AND f.visible_when IS NULL;
UPDATE fields f SET is_required = false, visible_when = 'widerlager_eingebaut == true' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND w.code = 'FLLTP-RHZ-05' AND s.code = 'FLL-TP-RHIZOM-2023' AND f.symbol = 'widerlager_material' AND f.is_required = true AND f.visible_when IS NULL;
UPDATE fields f SET is_required = false, visible_when = 'verlaengerung_beantragt == true' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND w.code = 'FLLTP-RHZ-20' AND s.code = 'FLL-TP-RHIZOM-2023' AND f.symbol = 'pruefgrundlagen_unveraendert' AND f.is_required = true AND f.visible_when IS NULL;
UPDATE fields f SET is_required = false, visible_when = 'verlaengerung_beantragt == true' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND w.code = 'FLLTP-RHZ-20' AND s.code = 'FLL-TP-RHIZOM-2023' AND f.symbol = 'produkt_aktuell_im_lieferprogramm' AND f.is_required = true AND f.visible_when IS NULL;
UPDATE fields f SET is_required = false, visible_when = 'verlaengerung_beantragt == true' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND w.code = 'FLLTP-RHZ-20' AND s.code = 'FLL-TP-RHIZOM-2023' AND f.symbol = 'rueckstellmuster_erneut_hinterlegt' AND f.is_required = true AND f.visible_when IS NULL;
UPDATE fields f SET is_required = false, visible_when = 'verlaengerung_beantragt == true' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND w.code = 'FLLTP-RHZ-20' AND s.code = 'FLL-TP-RHIZOM-2023' AND f.symbol = 'eidesstattliche_erklaerung_vorhanden' AND f.is_required = true AND f.visible_when IS NULL;
UPDATE fields f SET is_required = false, visible_when = 'verlaengerung_beantragt == true' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND w.code = 'FLLTP-RHZ-20' AND s.code = 'FLL-TP-RHIZOM-2023' AND f.symbol = 'verlangerung_zeitabschnitt_jahre' AND f.is_required = true AND f.visible_when IS NULL;
-- FLLTP-RHZ-05 REQ-06
-- §3.2 (p. 9): "Bei starrten Werkstoffen (z. B. Gussasphalt) kann auf ein Widerlager verzichtet werden" — the abutment term now applies only when installed (B-1); §5.2 (p. 13): "Die Kontrollgefäße sind wasserdicht auszuführen" added. Relaxes one term, adds one → sign-off.
UPDATE compliance_requirements cr SET condition = 'gefaess_innenmass_l_mm >= 800 AND gefaess_innenmass_b_mm >= 800 AND gefaess_innenmass_h_mm >= 250 AND anzahl_pruefgefaesse == 8 AND anzahl_kontrollgefaesse == 3 AND wasserablauf_durchmesser_mm == 40 AND kontrollgefaesse_wasserdicht == true AND (widerlager_eingebaut == false OR (widerlager_dicke_mm >= 9 AND widerlager_dicke_mm <= 11))', source_quote = '§3.2 (p. 9): "Bei starrten Werkstoffen (z. B. Gussasphalt) kann auf ein Widerlager verzichtet werden" — the abutment term now applies only when installed (B-1); §5.2 (p. 13): "Die Kontrollgefäße sind wasserdicht auszuführen" added. Relaxes one term, adds one → sign-off.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE cr.worksheet_template_id = w.id AND w.code = 'FLLTP-RHZ-05' AND s.code = 'FLL-TP-RHIZOM-2023' AND cr.code = 'REQ-06' AND cr.condition = 'gefaess_innenmass_l_mm >= 800 AND gefaess_innenmass_b_mm >= 800 AND gefaess_innenmass_h_mm >= 250 AND anzahl_pruefgefaesse == 8 AND anzahl_kontrollgefaesse == 3 AND wasserablauf_durchmesser_mm == 40 AND widerlager_dicke_mm >= 9 AND widerlager_dicke_mm <= 11';
-- FLLTP-RHZ-04 REQ-10
-- §5.8 (p. 15): "Je Gefäß von 800 x 800 mm sind 8 Pflanzen vorzusehen." + §5.2 (p. 13): "Alle nachfolgenden Angaben (z. B. Düngung, Pflanzdichte) … sind an die ggf. größer dimensionierten Gefäße anzupassen." (B-3). RULING: "≥ 8 · factor" (at least the scaled density; 9 plants in the minimum vessel would pass) versus exact equality (unsatisfiable for non-integer scaled counts).
UPDATE compliance_requirements cr SET condition = 'testpflanze_art == ''phragmites_australis'' AND pflanzdichte_pro_gefaess >= 8 * gefaess_skalierungsfaktor', source_quote = '§5.8 (p. 15): "Je Gefäß von 800 x 800 mm sind 8 Pflanzen vorzusehen." + §5.2 (p. 13): "Alle nachfolgenden Angaben (z. B. Düngung, Pflanzdichte) … sind an die ggf. größer dimensionierten Gefäße anzupassen." (B-3). RULING: "≥ 8 · factor" (at least the scaled density; 9 plants in the minimum vessel would pass) versus exact equality (unsatisfiable for non-integer scaled counts).'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE cr.worksheet_template_id = w.id AND w.code = 'FLLTP-RHZ-04' AND s.code = 'FLL-TP-RHIZOM-2023' AND cr.code = 'REQ-10' AND cr.condition = 'testpflanze_art == ''phragmites_australis'' AND pflanzdichte_pro_gefaess == 8';
-- FLLTP-RHZ-12 REQ-14
-- §5.2 (p. 13) scaling rule applied to the fertiliser quantities (B-3); the water-level and interval terms are untouched (their §7.3 page was not re-read in this session). RULING as REQ-10 ("≥ scaled" vs equality).
UPDATE compliance_requirements cr SET condition = 'wasserstand_max_ueber_vts_mm == 20 AND wasserstand_min_unter_vts_mm == 50 AND duenger_intervall_monate == 1 AND duenger_gabe_g >= 5 * gefaess_skalierungsfaktor AND duenger_loesung_l >= 20 * gefaess_skalierungsfaktor AND ersatz_pflanzen_periode_mon <= 3 AND halmschnitt_im_gruenen_zulaessig == false', source_quote = '§5.2 (p. 13) scaling rule applied to the fertiliser quantities (B-3); the water-level and interval terms are untouched (their §7.3 page was not re-read in this session). RULING as REQ-10 ("≥ scaled" vs equality).'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE cr.worksheet_template_id = w.id AND w.code = 'FLLTP-RHZ-12' AND s.code = 'FLL-TP-RHIZOM-2023' AND cr.code = 'REQ-14' AND cr.condition = 'wasserstand_max_ueber_vts_mm == 20 AND wasserstand_min_unter_vts_mm == 50 AND duenger_intervall_monate == 1 AND duenger_gabe_g == 5 AND duenger_loesung_l == 20 AND ersatz_pflanzen_periode_mon <= 3 AND halmschnitt_im_gruenen_zulaessig == false';
-- FLLTP-RHZ-20 REQ-22
-- §9 (p. 22): the four conditions hold "jedoch nur wenn" an extension is sought, "in Zeitabschnitten von 5 Jahren" (B-4 / A-61). A first-issue report is no longer blocked. Relaxes + adds the 5-year term → sign-off.
UPDATE compliance_requirements cr SET condition = 'IF verlaengerung_beantragt == true THEN pruefgrundlagen_unveraendert == true AND produkt_aktuell_im_lieferprogramm == true AND rueckstellmuster_erneut_hinterlegt == true AND eidesstattliche_erklaerung_vorhanden == true AND verlangerung_zeitabschnitt_jahre == 5', source_quote = '§9 (p. 22): the four conditions hold "jedoch nur wenn" an extension is sought, "in Zeitabschnitten von 5 Jahren" (B-4 / A-61). A first-issue report is no longer blocked. Relaxes + adds the 5-year term → sign-off.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE cr.worksheet_template_id = w.id AND w.code = 'FLLTP-RHZ-20' AND s.code = 'FLL-TP-RHIZOM-2023' AND cr.code = 'REQ-22' AND cr.condition = 'pruefgrundlagen_unveraendert == true AND produkt_aktuell_im_lieferprogramm == true AND rueckstellmuster_erneut_hinterlegt == true AND eidesstattliche_erklaerung_vorhanden == true';
-- FLLTP-RHZ-17 REQ-23 (new, block) — "muss … aufweisen" / "ist … zu lagern" → block (RULING: severity). Storage duration ≥ report validity (dates) is a field only.
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-23', 'Rückstellprobe — Fläche ≥ 0,5 m², Naht je Fügetechnik, Lagerung > 5 °C und < 25 °C trocken und dunkel (§6)', 'Retained sample — area ≥ 0.5 m², seam per joining technique, storage > 5 °C and < 25 °C dry and dark (§6)', 'rueckstellprobe_flaeche_m2 >= 0.5 AND rueckstellprobe_enthaelt_naht_je_fuegetechnik == true AND rueckstellprobe_lager_temp_min_C > 5 AND rueckstellprobe_lager_temp_max_C < 25 AND rueckstellprobe_trocken_dunkel == true', '§6', 'block', 'Coverage block 4b (2026-09-29): "muss … aufweisen" / "ist … zu lagern" → block (RULING: severity). Storage duration ≥ report validity (dates) is a field only.', 'Von der Abdichtung ist vom Prüfinstitut vor und nach der Untersuchung eine Rückstellprobe zu nehmen. Das entnommene Teilstück muss zumindest eine Nahtstelle pro Fügetechnik bzw. eine Arbeitsunterbrechungsfuge enthalten und eine Fläche von mindestens 0,5 m² aufweisen. Die Rückstellprobe ist bei Temperaturen über 5 °C und unter 25 °C trocken und dunkel beim Prüfinstitut zu lagern. Die Dauer der Lagerung muss mindestens der Gültigkeitsdauer des Prüfberichts entsprechen (s. Abschnitt 8). Stoffliche Unverträglichkeiten sind bei der Lagerung zu beachten.', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLLTP-RHZ-17' AND s.code = 'FLL-TP-RHIZOM-2023'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLLTP-RHZ-19 REQ-24 (new, warn) — "grundsätzlich" → warn (RULING). Field exists (required) but was never compared.
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-24', 'Prüfbericht — Gültigkeitsdauer grundsätzlich 10 Jahre (§9)', 'Test report — validity period 10 years in principle (§9)', 'gueltigkeitsdauer_jahre == 10', '§9', 'warn', 'Coverage block 4b (2026-09-29): "grundsätzlich" → warn (RULING). Field exists (required) but was never compared.', '„Der Prüfbericht wurde am ........ erstellt und hat grundsätzlich eine Gültigkeitsdauer von 10 Jahren.“', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLLTP-RHZ-19' AND s.code = 'FLL-TP-RHIZOM-2023'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLLTP-RHZ-09 REQ-25 (new, block) — Definition with fixed dimensions → block (RULING: severity; the diameter field existed without a gate).
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-25', 'Standrohre — zwei Rohre ∅ 50 mm, Länge 200 mm (§3.5)', 'Standpipes — two pipes ∅ 50 mm, length 200 mm (§3.5)', 'standrohr_anzahl == 2 AND standrohr_durchmesser_mm == 50 AND standrohr_laenge_mm == 200', '§3.5', 'block', 'Coverage block 4b (2026-09-29): Definition with fixed dimensions → block (RULING: severity; the diameter field existed without a gate).', 'Durch zwei eingelassene Rohre (∅ 50 mm, Länge 200 mm) aus pflanzenverträglichen Werkstoffen (z. B. PE) wird in der Vegetationstragschicht die Kontrolle des Wasserstandes und der Wasserqualität sichergestellt.', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLLTP-RHZ-09' AND s.code = 'FLL-TP-RHIZOM-2023'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLLTP-RHZ-06 REQ-26 (new, block) — "geforderten Schichtdicke von (170 ±10) mm" → block. Largely implied by REQ-13 (20 ±5 + 150 ±5) but printed as its own figure; reads the now-computed vts_gesamt_dicke_mm.
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-26', 'Vegetationstragschicht — Gesamtdicke (170 ±10) mm (§5.6)', 'Vegetation substrate — total thickness (170 ±10) mm (§5.6)', 'vts_gesamt_dicke_mm >= 160 AND vts_gesamt_dicke_mm <= 180', '§5.6; §7.1', 'block', 'Coverage block 4b (2026-09-29): "geforderten Schichtdicke von (170 ±10) mm" → block. Largely implied by REQ-13 (20 ±5 + 150 ±5) but printed as its own figure; reads the now-computed vts_gesamt_dicke_mm.', 'Der Substratbedarf beträgt bei der geforderten Schichtdicke von (170 ±10) mm ca. 110 l je Versuchsgefäß (800 x 800 mm).', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLLTP-RHZ-06' AND s.code = 'FLL-TP-RHIZOM-2023'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
COMMIT;
